// Worker entry: the OpenNext handler plus the Cron Triggers that replace
// the in-process timer in src/instrumentation.ts and MongoDB's TTL indexes.
// @ts-ignore -- generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";
import { deleteExpiredRows, purgeExpiredAnonymousDocs } from "./src/lib/db/purge";
import type { D1 } from "./src/lib/d1";

const DAILY_PURGE = "17 3 * * *";

export default {
  fetch: handler.fetch,

  async scheduled(event: { cron: string; scheduledTime: number }, env: { DB: D1 }) {
    if (event.cron === DAILY_PURGE) {
      const deleted = await purgeExpiredAnonymousDocs(event.scheduledTime, env.DB);
      console.log(JSON.stringify({ level: "info", scope: "expiry", message: "Purged expired anonymous pages", deleted }));
    } else {
      const deleted = await deleteExpiredRows(event.scheduledTime, env.DB);
      console.log(JSON.stringify({ level: "info", scope: "ttl", message: "Deleted expired rows", deleted }));
    }
  },
};
